=== pack.mjs ===
import signalTeardownRouting from './signal-teardown-routing.mjs';

// Technology pack: a native macOS app — the app bundle, TCC and Hardened
// Runtime, the Developer ID / notarization / DMG distribution lane, and the
// process-lifecycle rules a Mac agent app has to get right.
//
// Fingerprint: a `Package.swift` at the repo root or one directory down (a
// monorepo's `mac/` dir), never deeper, so a nested fixture package can't trip
// detection. The marker only SUSPECTS the pack — a Swift package can be a
// library or an iOS-only target, and declaration stays the project's call. An
// iOS app declares `ios`; a Flutter app's macOS runner declares `flutter`.
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  id: 'macos',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'native macOS apps: app-bundle assembly, TCC usage strings, Hardened Runtime entitlements, Developer ID signing, notarization and DMG distribution',
    excludes: 'Mac App Store submission — app-store-release; iPhone app targets — ios; workflow YAML mechanics — github-actions',
  },
  badge: 'badge.svg',
  marker: 'Package.swift (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'Package.swift'),
  prose: 'RULES.md',
  // Two checks, both on the exit-path rules — the only ones whose violation has
  // a static signature that is false-positive-free *because the rule is itself
  // conditional*: each fires only where the tree shows the posture the rule is
  // about (terminate-time teardown; an AppKit app that installs a capture tap).
  // sudden-termination-vs-teardown lives in declared-checks.json beside this
  // file; signal-teardown-routing stays coded for its ordered-occurrence arm.
  // Everything else in RULES.md stays prose — runtime device behaviour, a CI
  // lane's shape, or a plist/entitlement judgment call, none of which a scan can
  // separate from a healthy repo.
  worldRules: [signalTeardownRouting],
};

import { finding } from '../../engine/checks/helpers/findings.mjs';
import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';

// Converted from this pack's exit-path prose: `NSApplication` installs no signal
// handlers, so a bare SIGTERM (Activity Monitor's Quit, `killall`), SIGINT or
// SIGHUP kills the process with no teardown at all — leaving a capture tap's
// CoreAudio IOProc registered on the device, which is what wedges some USB input
// devices until they are physically re-plugged.
//
// Gated twice, so it speaks only where the rule applies: the tree must be an
// AppKit app (a command-line tool has no `NSApp.terminate` to route into) AND it
// must install a capture tap (no tap, no IOProc to abandon, nothing at stake).
// Everything is read with comments stripped — prose describing the trap is not
// an implementation of it, nor evidence against one.
//
// Three arms:
//   1. nothing anywhere routes those signals — any of the three mechanisms a Mac
//      app plausibly uses counts as routing (`DispatchSource.makeSignalSource`,
//      `sigaction`, a direct `signal(SIGTERM, …)` handler);
//   2. routing exists but one of the three signals is named nowhere in the
//      sources — the unrouted one stays fatal by default;
//   3. `SIG_IGN` comes after the source is resumed — until the default action is
//      ignored, a signal landing in the gap still terminates the process outright.
//
// Arm 3 compares offsets rather than parsing scopes, and deliberately only looks
// at the first `.resume()` that follows the file's first `makeSignalSource(` — an
// unrelated `resume()` earlier in the file (a URLSession task, a dispatch queue)
// is then not this rule's business.
//
// Blocking: every arm describes a path that skips teardown silently, and the
// damage shows up on hardware rather than in the build.

const SWIFT = /\.swift$/;

const SIGNALS = ['SIGTERM', 'SIGINT', 'SIGHUP'];

// AppKit, not a CLI: only an app with an NSApplication has NSApp.terminate to
// route into, and only it gets `applicationWillTerminate` at all.
const APPKIT = /\bNSApplicationDelegate\b|\bNSApplicationMain\b|\bNSApp\b/;
// A capture tap is what registers the IOProc this rule protects.
const TAP = /\binstallTap\s*\(/;

const MAKE_SOURCE = /\bmakeSignalSource\s*\(/;
const ROUTING = [
  MAKE_SOURCE,
  /\bsigaction\s*\(/,
  new RegExp(`\\bsignal\\s*\\(\\s*(?:${SIGNALS.join('|')})\\b`),
];
const SIG_IGN = /\bsignal\s*\([^)]*SIG_IGN/;
const RESUME = /\.resume\s*\(\s*\)/g;

const lineOf = (text, index) => text.slice(0, index).split('\n').length;

const rule = {
  id: 'signal-teardown-routing',
  severity: 'blocking',
  description: 'An AppKit app that installs a capture tap routes SIGTERM/SIGINT/SIGHUP into NSApp.terminate, with SIG_IGN before resume() (*.swift)',
  doc: 'packs/macos/RULES.md',
  why: 'NSApplication installs no signal handlers, so an unrouted SIGTERM/SIGINT/SIGHUP kills the process with no teardown and abandons the capture tap\'s IOProc on the device — the state that wedges some USB input devices until they are re-plugged',

  run(ctx) {
    const sources = new Map();
    for (const file of ctx.files.filter((f) => SWIFT.test(f))) {
      const text = ctx.read(file);
      if (text !== null) sources.set(file, stripComments(text));
    }

    const isApp = [...sources.values()].some((t) => APPKIT.test(t));
    const tapSite = [...sources.entries()].find(([, t]) => TAP.test(t));
    if (!isApp || !tapSite) return [];

    const routingFiles = [...sources.entries()].filter(([, t]) => ROUTING.some((r) => r.test(t)));

    if (routingFiles.length === 0) {
      const [file, text] = tapSite;
      return [finding(rule, {
        file,
        line: lineOf(text, text.search(TAP)),
        what: `a capture tap is installed in ${file} but nothing in the sources routes termination signals to NSApp.terminate`,
        fix: 'map [SIGTERM, SIGINT, SIGHUP] to `DispatchSource.makeSignalSource(signal:queue:)` handlers that call `NSApp.terminate(nil)` — calling `signal(sig, SIG_IGN)` before `resume()`, and holding the sources in a top-level `let` so they outlive setup',
      })];
    }

    const out = [];

    // Arm 2: a signal named nowhere in the sources is a signal nothing routes.
    const unrouted = SIGNALS.filter(
      (s) => ![...sources.values()].some((t) => new RegExp(`\\b${s}\\b`).test(t))
    );
    if (unrouted.length > 0) {
      const [file, text] = routingFiles[0];
      out.push(finding(rule, {
        file,
        line: lineOf(text, Math.max(text.search(MAKE_SOURCE), 0)),
        what: `signal routing exists but ${unrouted.join(', ')} appears nowhere in the sources`,
        fix: `route ${unrouted.join(', ')} the same way as the signals already handled — each of them is fatal by default and leaves the tap installed`,
      }));
    }

    // Arm 3: SIG_IGN must precede the resume() of the sources it protects.
    for (const [file, text] of routingFiles) {
      const setup = text.search(MAKE_SOURCE);
      if (setup < 0) continue;
      RESUME.lastIndex = setup;
      const resumed = RESUME.exec(text);
      if (resumed === null) continue;
      const ignore = text.search(SIG_IGN);
      if (ignore >= 0 && ignore < resumed.index) continue;
      out.push(finding(rule, {
        file,
        line: lineOf(text, resumed.index),
        what: ignore < 0
          ? `${file} resumes a signal source without ever calling signal(…, SIG_IGN)`
          : `${file} calls signal(…, SIG_IGN) only after resume()`,
        fix: 'call `signal(sig, SIG_IGN)` before `source.resume()` — until the default action is ignored, a signal arriving in the gap still terminates the process outright',
      }));
    }

    return out;
  },
};

export default rule;
=== declared-checks.json ===
[
  {
    "id": "sudden-termination-vs-teardown",
    "severity": "blocking",
    "failureMessage": "sudden termination licenses macOS to SIGKILL the app at logout, skipping applicationWillTerminate and every teardown there — an abandoned CoreAudio tap can wedge a USB device until re-plugged",
    "relevantWhen": {
      "someTrackedFileContains": {
        "pathMatching": "/\\.swift$/",
        "text": "/\\bapplicationWillTerminate\\b|\\binstallTap\\s*\\(/",
        "ignoringComments": true
      }
    },
    "scanFiles": "/\\.plist$/",
    "checkEachFile": [
      {
        "forbid": "/<\\s*key\\s*>\\s*NSSupportsSuddenTermination\\s*<\\s*\\/\\s*key\\s*>\\s*(?:<!--[\\s\\S]*?-->\\s*)*<\\s*[Tt]rue/",
        "what": "declares NSSupportsSuddenTermination <true/> in an app that has teardown to run at terminate",
        "fix": "remove the NSSupportsSuddenTermination key (or set it <false/>) — the app must get its chance to remove its tap and stop its engine on the way out"
      }
    ]
  }
]

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup } from '../../engine-tests/helpers.mjs';
import { buildContext } from '../../engine/checks/helpers/repo-context.mjs';
import signalRouting from '../../packs/macos/signal-teardown-routing.mjs';

const run = (root) => signalRouting.run(buildContext({ root, mode: 'all' }));

const DELEGATE = `import AppKit

final class AppDelegate: NSObject, NSApplicationDelegate {
  func applicationDidFinishLaunching(_ n: Notification) { AudioHub.shared.start() }
}
`;

const HUB = `import AVFoundation

final class AudioHub {
  static let shared = AudioHub()
  func start() {
    engine.inputNode.installTap(onBus: 0, bufferSize: 4096, format: fmt) { _, _ in }
  }
}
`;

const ROUTING = `import AppKit

let signalSources = [SIGTERM, SIGINT, SIGHUP].map { sig -> DispatchSourceSignal in
  signal(sig, SIG_IGN)
  let source = DispatchSource.makeSignalSource(signal: sig, queue: .main)
  source.setEventHandler { NSApp.terminate(nil) }
  source.resume()
  return source
}
`;

const app = (files) => makeRepo({ changed: {
  'Sources/App/AppDelegate.swift': DELEGATE,
  'Sources/App/AudioHub.swift': HUB,
  ...files,
} });

test('signal-teardown-routing: flags a capture app that routes no signals at all', () => {
  const root = app({});
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].rule, 'signal-teardown-routing');
    assert.equal(findings[0].severity, 'blocking');
    assert.equal(findings[0].file, 'Sources/App/AudioHub.swift');
    assert.equal(findings[0].line, 6);
    assert.match(findings[0].what, /nothing in the sources routes termination signals/);
    assert.match(findings[0].fix, /makeSignalSource/);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: flags a signal nothing in the sources names', () => {
  const root = app({
    'Sources/App/main.swift': ROUTING.replace(', SIGHUP', ''),
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.match(findings[0].what, /SIGHUP appears nowhere/);
    assert.match(findings[0].fix, /SIGHUP/);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: flags SIG_IGN called only after resume()', () => {
  const root = app({
    'Sources/App/main.swift': `import AppKit

let signalSources = [SIGTERM, SIGINT, SIGHUP].map { sig -> DispatchSourceSignal in
  let source = DispatchSource.makeSignalSource(signal: sig, queue: .main)
  source.setEventHandler { NSApp.terminate(nil) }
  source.resume()
  signal(sig, SIG_IGN)
  return source
}
`,
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].line, 6);
    assert.match(findings[0].what, /SIG_IGN\) only after resume/);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: flags a resumed source with no SIG_IGN anywhere', () => {
  const root = app({
    'Sources/App/main.swift': ROUTING.replace('  signal(sig, SIG_IGN)\n', ''),
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.match(findings[0].what, /without ever calling signal\(…, SIG_IGN\)/);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: clean when all three are routed and SIG_IGN precedes resume', () => {
  const root = app({ 'Sources/App/main.swift': ROUTING });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: NOT flagged for a command-line tool (FP guard)', () => {
  // No NSApplication: there is no NSApp.terminate to route into, and this rule
  // has no opinion about how a CLI handles signals.
  const root = makeRepo({ changed: { 'Sources/tool/main.swift': HUB } });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: NOT flagged for an app that installs no tap (FP guard)', () => {
  // No tap, no IOProc to abandon — an app with nothing at stake is not this
  // rule's business, however it handles signals.
  const root = makeRepo({ changed: { 'Sources/App/AppDelegate.swift': DELEGATE } });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: accepts sigaction as routing (FP guard)', () => {
  const root = app({
    'Sources/App/main.swift': `import AppKit
var action = sigaction()
for sig in [SIGTERM, SIGINT, SIGHUP] { sigaction(sig, &action, nil) }
`,
  });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: an unrelated resume() above the setup is not the ordering bug (FP guard)', () => {
  const root = app({
    'Sources/App/main.swift': `import AppKit

URLSession.shared.dataTask(with: url) { _, _, _ in }.resume()

${ROUTING}`,
  });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('signal-teardown-routing: NOT flagged when only a comment describes the routing (FP guard)', () => {
  // Comments are stripped: prose naming makeSignalSource is not an implementation,
  // so the app still reads as unrouted rather than as correctly routed.
  const root = app({
    'Sources/App/main.swift': `import AppKit
// TODO: route SIGTERM/SIGINT/SIGHUP with DispatchSource.makeSignalSource and SIG_IGN
NSApplication.shared.run()
`,
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.match(findings[0].what, /nothing in the sources routes termination signals/);
  } finally { cleanup(root); }
});

import { fileURLToPath } from 'node:url';
import { ruleTester } from '../../engine-tests/helpers.mjs';
import { loadDeclaredChecks } from '../../engine/checks/helpers/pattern-rules.mjs';

const suddenTermination = loadDeclaredChecks(
  fileURLToPath(new URL('../../packs/macos', import.meta.url)),
).find((r) => r.id === 'sudden-termination-vs-teardown');

const DELEGATE = `import AppKit

final class AppDelegate: NSObject, NSApplicationDelegate {
  func applicationWillTerminate(_ notification: Notification) {
    AudioHub.shared.stop()
  }
}
`;

const plist = (body) => `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleName</key>
  <string>Fixture</string>
${body}
</dict>
</plist>
`;

const SUDDEN_TRUE = plist('  <key>NSSupportsSuddenTermination</key>\n  <true/>');

ruleTester(suddenTermination, {
  flagged: {
    'the key set true in an app with terminate teardown': {
      files: { 'Sources/App/AppDelegate.swift': DELEGATE, 'Resources/Info.plist': SUDDEN_TRUE },
      // The declared form judges the whole plist (the key/value pair spans
      // lines), so the finding anchors at the file, not a line.
      at: [{
        file: 'Resources/Info.plist', line: null, severity: 'blocking',
        fix: /remove the NSSupportsSuddenTermination key/,
      }],
    },
    'an installTap tap alone counts as teardown to lose (no delegate method at all)': {
      files: {
        'Sources/App/AudioHub.swift':
          'engine.inputNode.installTap(onBus: 0, bufferSize: 4096, format: fmt) { _, _ in }\n',
        'Info.plist': SUDDEN_TRUE,
      },
      at: [{ file: 'Info.plist' }],
    },
  },
  clean: {
    'the key set <false/> is the explicit opt-OUT, never a finding (FP guard)': {
      files: {
        'Sources/App/AppDelegate.swift': DELEGATE,
        'Resources/Info.plist': plist('  <key>NSSupportsSuddenTermination</key>\n  <false/>'),
      },
    },
    'an app that runs nothing at terminate keeps the optimisation (FP guard)': {
      files: {
        'Sources/App/main.swift': 'import AppKit\nNSApplication.shared.run()\n',
        'Info.plist': SUDDEN_TRUE,
      },
    },
    'a comment naming the teardown is not teardown (FP guard)': {
      files: {
        'Sources/App/main.swift': '// we deliberately implement no applicationWillTerminate here\nimport AppKit\n',
        'Info.plist': SUDDEN_TRUE,
      },
    },
    'the key named only in prose stays quiet — *.plist is the whole scope (FP guard)': {
      files: {
        'Sources/App/AppDelegate.swift': DELEGATE,
        'docs/lifecycle.md': 'Never add NSSupportsSuddenTermination — see the pack.\n',
