  ['a minute below the band', { [WF]: scheduled(at('5 4 * * *')) }, 1],
  ['a minute above the band', { [WF]: scheduled(at('55 * * * *')) }, 1],
  ['a comma list is not a fixed minute', { [WF]: scheduled(at('0,30 * * * *')) }, 1],
  ['every entry judged, unquoted scalar reads the same', { [WF]: scheduled(`${at('44 * * * *')}\n    - cron: 0 12 * * *   # midday sweep`) }, 1],
  ['a fixed minute inside the band', { [WF]: scheduled(at('44 3 * * *')) }, 0],
  ['band inclusive low end', { [WF]: scheduled(at('10 * * * *')) }, 0],
  ['band inclusive high end', { [WF]: scheduled(at('50 * * * *')) }, 0],
  ['cron mapping key outside schedule block (FP guard)', { [WF]: `name: Manual
on:
