jobs:
  run:
    runs-on: ubuntu-latest
    steps:
      - run: echo hi
` }, 0],
  ['dash-cron under with.schedules after schedule closed (FP guard)', { [WF]: `name: Nightly
on:
  schedule:
    - cron: '44 3 * * *'

jobs:
  run:
    runs-on: ubuntu-latest
    steps:
      - uses: acme/mirror-schedule@v1
        with:
          schedules:
            - cron: '0 * * * *'
` }, 0],
  ['cron mapping key inside step schedule input (FP guard)', { [WF]: `name: Nightly
on:
  workflow_dispatch:
jobs:
  run:
    runs-on: ubuntu-latest
    steps:
      - uses: acme/scheduler@v1
