  ['vendored scheduler excluded (FP guard)', { '.github/workflows/claudinite-scheduler.yml': scheduled(at('0 * * * *')) }, 0],
  ['cron outside .github/workflows out of scope (FP guard)', { 'deploy/cron.yml': scheduled(at('0 * * * *')) }, 0],
];

let failures = 0;
for (const [name, files, expected] of cases) {
  const findings = run(files);
  const ok = findings.length === expected;
  if (!ok) failures++;
  console.log(`${ok ? 'OK  ' : 'FAIL'} ${name}: expected ${expected}, got ${findings.length}${ok ? '' : ' -> ' + JSON.stringify(findings)}`);
}
